eval("/* Implmentation of Schoolbox flyout menus */\n(function ($) {\n  $.fn.flyout = function (options) {\n    var settings = $.extend({\n      attr: 'data-menu',\n      element: 'li'\n    }, options);\n    return this.each(function () {\n      var btn = $(this);\n      var html = $('html');\n      var menuref = '#' + btn.attr(settings.attr);\n      var list = btn.parent(settings.element);\n\n      var fn = function (event) {\n        // if we clicked somewhere on the menu, just reattach the listener\n        if ($(event.target).closest(menuref).length == 1) {\n          html.one('click', fn);\n        } // we clicked elsewhere (including the button itself), so close the flyout\n        else {\n            list.removeClass('open');\n          }\n      }; // attach the listener\n\n\n      btn.on('click', function (e) {\n        e.preventDefault(); // is already open\n\n        if (list.hasClass('open')) {\n          // we've clicked on the button, which is already open - the html listener should close it for us.....\n          return true;\n        } // trigger a click on the document, so that if a flyout is open it gets closed\n\n\n        html.trigger('click'); // is not open: attach a close listener for this\n\n        html.one('click', fn); // open it\n\n        list.addClass('open');\n        return false;\n      });\n    });\n  };\n})(jQuery);\n\n//# sourceURL=webpack://schoolbox/./www/static/js/shared/sidemenu/jquery.flyout.js?");

